function rp_write($path,array $entities){$f=new DomainBackupFormat();$config=array('certverify_fields'=>array('exists'=>true,'value'=>array()),'certverify_retired_fields'=>array('exists'=>true,'value'=>array()),'certverify_settings'=>array('exists'=>true,'value'=>array()));$counts=array('issuers'=>0,'programs'=>0,'recipients'=>0,'credential_series'=>0,'credential_numbers'=>0,'credential_versions'=>0,'credential_events'=>0);$max=array_fill_keys(array_keys($counts),0);foreach($entities as $e){$counts[$e['entity']]++;$max[$e['entity']]=max($max[$e['entity']],(int)$e['data']['id']);}$bounds=array();foreach($counts as $k=>$n)$bounds[$k]=array('count'=>$n,'max_id'=>$max[$k]);$manifest=array('type'=>'manifest','format'=>DomainBackupFormat::FORMAT,'format_version'=>DomainBackupFormat::VERSION,'plugin_version'=>'1.5.4','generated_at'=>'2026-08-22T00:00:00Z','generation'=>'g1','entities'=>$bounds,'configuration'=>$config,'configuration_hash'=>hash('sha256',wp_json_encode($config,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)));$lines=array();$line=$f->encode_line($manifest);$lines[]=$line;$hash=$f->next_hash('',$line);foreach($entities as $e){$line=$f->encode_line(array('type'=>'entity')+$e);$lines[]=$line;$hash=$f->next_hash($hash,$line);} $lines[]=$f->encode_line(array('type'=>'integrity','records'=>count($entities),'chain_sha256'=>$hash));file_put_contents($path,implode('',$lines));}
function rp_row($entity,array $values){$row=array_fill_keys(SchemaManager::column_names($entity),null);foreach($row as $k=>$v){if('created_at'===$k||'updated_at'===$k)$row[$k]='2026-08-22 00:00:00';}return array_replace($row,$values);}
